package main

import (
	"context"
	"testing"
)

func TestHistoryImportUsesSharedAdmissionLifecycle(t *testing.T) {
	ctx := context.Background()
	release, err := acquireHistoryHeavyBudget(ctx, "import-user", 1)
	if err != nil { t.Fatal(err) }
	release()
	if _, err := acquireHistoryHeavyBudget(ctx, "import-user", 1); err != nil { t.Fatal(err) }
}
